  "track_plan": [
    {
      "id": "drums",
      "name": "Drums",
      "role": "drums / pulse",
      "register": {
        "low": 35,
        "high": 81
      },
      "instrument_hint": "electronic drum machine, kick, snare, hi-hats, clap",
      "section_jobs": [
        {
          "section_id": "intro",
          "intent": "ambient kick pulse and soft off-beat hi-hat, no snare",
          "density": "sparse"
        },
        {
          "section_id": "verse1",
          "intent": "kick on 1 and 3, snare on 2 and 4, closed hats",
          "density": "medium"
        },
        {
          "section_id": "pre1",
          "intent": "add 8th-note hats and fill into chorus",
          "density": "medium"
        },
        {
          "section_id": "chorus1",
          "intent": "full groove with open hats and crash at section start",
          "density": "dense"
        },
        {
          "section_id": "verse2",
          "intent": "similar to verse1 but with ghost snare or percussion variation",
          "density": "medium"
        },
        {
          "section_id": "chorus2",
          "intent": "same as chorus1 plus extra percussion layer",
          "density": "dense"
        },
        {
          "section_id": "outro",
          "intent": "kick and hat fade, no snare",
          "density": "sparse"
        }
      ]
    },
    {
      "id": "bass",
      "name": "Bass",
      "role": "bass",
      "register": {
        "low": 28,
        "high": 55
      },
      "instrument_hint": "warm analog bass, sustained and plucked",
      "section_jobs": [
        {
          "section_id": "intro",
          "intent": "long root notes only on downbeats, gaps",
          "density": "sparse"
        },
        {
          "section_id": "verse1",
          "intent": "root on downbeats, octave jumps on bars 4 and 8",
          "density": "medium"
        },
        {
          "section_id": "pre1",
          "intent": "walking 8th-note pulse on chord roots",
          "density": "medium"
        },
        {
          "section_id": "chorus1",
          "intent": "syncopated bassline with passing tones, sustained notes",
          "density": "dense"
        },
        {
          "section_id": "verse2",
          "intent": "variation: add rests and a fill at bar 7",
          "density": "medium"
        },
        {
          "section_id": "chorus2",
          "intent": "same as chorus1 with added upper octave stab",
          "density": "dense"
        },
        {
          "section_id": "outro",
          "intent": "sustained low A, fading",
          "density": "sparse"
        }
      ]
    },
    {
      "id": "chords",
      "name": "Main Chords",
      "role": "main chords",
      "register": {
        "low": 48,
        "high": 76
      },
      "instrument_hint": "poly synth keys, mid register",
      "section_jobs": [
        {
          "section_id": "intro",
          "intent": "warm sustained Am–F pads, sparse",
          "density": "sparse"
        },
        {
          "section_id": "verse1",
          "intent": "comp on beats 2 and 4, leave space for vocal",
          "density": "sparse"
        },
        {
          "section_id": "pre1",
          "intent": "block chords on each downbeat, increase density",
          "density": "medium"
        },
        {
          "section_id": "chorus1",
          "intent": "driving 8th-note stabs with open voicings",
          "density": "dense"
        },
        {
          "section_id": "verse2",
          "intent": "arpeggiated lower voicing, less blocky than verse1",
          "density": "medium"
        },
        {
          "section_id": "chorus2",
          "intent": "fuller chords with added 9ths",
          "density": "dense"
        },
        {
          "section_id": "outro",
          "intent": "sustained Am-F ending",
          "density": "sparse"
        }
      ]
    },
    {
      "id": "counter",
      "name": "Counter Motif",
      "role": "counter motif",
      "register": {
        "low": 60,
        "high": 84
      },
      "instrument_hint": "bell/pluck arpeggio",
      "section_jobs": [
        {
          "section_id": "intro",
          "intent": "two-note bell motif every other bar",
          "density": "sparse"
        },
        {
          "section_id": "verse1",
          "intent": "answer phrase after vocal lines, bars 2,4,6",
          "density": "sparse"
        },
        {
          "section_id": "pre1",
          "intent": "arpeggiated 8th-note motif ascending",
          "density": "medium"
        },
        {
          "section_id": "chorus1",
          "intent": "doubles hook rhythm but different pitch class",
          "density": "medium"
        },
        {
          "section_id": "verse2",
          "intent": "motif transposed up a fourth, more present",
          "density": "medium"
        },
        {
          "section_id": "chorus2",
          "intent": "countermelody fills gaps",
          "density": "dense"
        },
        {
          "section_id": "outro",
          "intent": "final motif echo",
          "density": "sparse"
        }
      ]
    },
    {
      "id": "pad",
      "name": "Pad",
      "role": "pad",
      "register": {
        "low": 48,
        "high": 72
      },
      "instrument_hint": "soft analog pad, slow attack",
      "section_jobs": [
        {
          "section_id": "intro",
          "intent": "low Am/F sustained pad, very quiet",
          "density": "sparse"
        },
        {
          "section_id": "verse1",
          "intent": "soft pad swells on chord changes",
          "density": "sparse"
        },
        {
          "section_id": "pre1",
          "intent": "pad sustains full chords with CC swells",
          "density": "medium"
        },
        {
          "section_id": "chorus1",
          "intent": "wide stereo pad, full register",
          "density": "dense"
        },
        {
          "section_id": "verse2",
          "intent": "slightly brighter pad than verse1",
          "density": "medium"
        },
        {
          "section_id": "chorus2",
          "intent": "full pad with top note",
          "density": "dense"
        },
        {
          "section_id": "outro",
          "intent": "pad fades to single note",
          "density": "sparse"
        }
      ]
    },
    {
      "id": "transition",
      "name": "Transition Texture",
      "role": "transition texture",
      "register": {
        "low": 40,
        "high": 90
      },
      "instrument_hint": "filtered noise riser / reverse reverb",
      "section_jobs": [
        {
          "section_id": "intro",
          "intent": "reverse reverb swell into bar 4",
          "density": "sparse"
        },
        {
          "section_id": "verse1",
          "intent": "one riser at bar 8 into pre",
          "density": "sparse"
        },
        {
          "section_id": "pre1",
          "intent": "filtered noise rise over 4 bars",
          "density": "medium"
        },
        {
          "section_id": "chorus1",
          "intent": "downlifter at bar 8 into verse2",
          "density": "sparse"
        },
        {
          "section_id": "verse2",
          "intent": "riser at end into chorus2",
          "density": "sparse"
        },
        {
          "section_id": "chorus2",
          "intent": "impacts and sweeps",
          "density": "medium"
        },
        {
          "section_id": "outro",
          "intent": "fade-out texture",
          "density": "sparse"
        }
      ]
    },
    {
      "id": "hook",
      "name": "Instrumental Hook",
      "role": "optional instrumental hook",
      "register": {
        "low": 64,
        "high": 88
      },
      "instrument_hint": "glassy lead synth",
      "section_jobs": [
        {
          "section_id": "intro",
          "intent": "signature hook phrase in bars 1-2, then rest",
          "density": "sparse"
        },
        {
          "section_id": "verse1",
          "intent": "no hook, leave vocal space",
          "density": "sparse"
        },
        {
          "section_id": "pre1",
          "intent": "short echo of hook at bar 16",
          "density": "sparse"
        },
        {
          "section_id": "chorus1",
          "intent": "hook phrase in bars 18-19 and 22-23, not continuous",
          "density": "medium"
        },
        {
          "section_id": "verse2",
          "intent": "hook only at end bar 32 leading to chorus2",
          "density": "sparse"
        },
        {
          "section_id": "chorus2",
          "intent": "hook doubled an octave up, more present",
          "density": "medium"
        },
        {
          "section_id": "outro",
          "intent": "final hook phrase, then rest",
          "density": "sparse"
        }
      ]
    }
  ],
  "motif_strategy": "A three-note descending motif (A-G-E) anchors the counter and hook; it appears in intro, echoes in verse answers, expands in pre and chorus, and returns in outro. The motif avoids the vocal register in verses and only becomes a full melodic statement in instrumental sections.",
  "harmony_strategy": "Verse and chorus use i–VI–III–VII (Am–F–C–G) with voice leading in the pad and chords. Pre-chorus moves Dm–Em–F–G to create lift; chorus adds upper extensions (9ths) and wider voicings. Bass shifts from root-position to inversions in the second verse.",
  "groove_strategy": "Drums progress from sparse kick/hat to full backbeat in choruses. Bass locks with kick in verses and becomes syncopated in choruses. Pre-chorus adds 8th-note hats for momentum. Verse 2 uses a half-time feel until bar 7, then returns to full time. Outro strips back to kick, pad, and hook echo."
}
